#include "uppercase_parent_cases.inc"
struct NumericHarness {
 std::vector<uint32_t> raw;unsigned draws=0, attempts=0;uint32_t fallback=0;unsigned refuse=0;
 std::vector<uint32_t> drawTimes;std::vector<ds_preview::Event> events;std::vector<uint32_t> times;uint32_t now=0;
 static bool random(void* c,uint32_t& out){auto& h=*static_cast<NumericHarness*>(c);unsigned n=h.draws++;h.drawTimes.push_back(h.now);out=n<h.raw.size()?h.raw[n]:h.fallback;return true;}
 static ds_preview::Accept sink(void* c,const ds_preview::Event& e){auto& h=*static_cast<NumericHarness*>(c);++h.attempts;if(h.refuse){--h.refuse;return ds_preview::Accept::Retry;}h.events.push_back(e);h.times.push_back(h.now);return ds_preview::Accept::Accepted;}
};
static void execute(const char* s,ds_preview::Program& p,ds_preview::Runtime& rt,NumericHarness& h,uint32_t start=0){check(p.compile(s,strlen(s)),"numeric/jitter source compiles");rt.randomReader=NumericHarness::random;rt.randomContext=&h;check(rt.start(p,NumericHarness::sink,&h,start),"runtime starts");for(unsigned i=0;i<20000&&rt.state()==ds_preview::State::Running;++i){h.now=start+i;rt.tick(h.now);}}
static uint16_t variable(ds_preview::Runtime& r,const char* n){uint16_t v=0;check(r.variable(n,v),"result variable initialized");return v;}
static void numeric(const char* s,NumericHarness& h,uint16_t expected){ds_preview::Program p;ds_preview::Runtime rt;execute(s,p,rt,h);check(rt.state()==ds_preview::State::Completed,"numeric runtime completed");check(variable(rt,"$v")==expected,"numeric value exact");}
static void group(const char* command,const char* alphabet){for(unsigned i=0;i<strlen(alphabet);++i){lower::reset();rng_mock::reset();rng_mock::fallback=i;std::string s=std::string(command)+"\n";completed(s.c_str());unsigned char c=alphabet[i];uint8_t usage=0,mods=0;if(c>='a'&&c<='z')usage=4+c-'a';else if(c>='A'&&c<='Z'){usage=4+c-'A';mods=2;}else if(c>='0'&&c<='9')usage=c=='0'?39:30+c-'1';else{const char* specials="!@#$%^&*()";const char* at=strchr(specials,c);check(at!=nullptr,"explicit special alphabet");usage=30+(at-specials);mods=2;}upperOnly(usage,mods);check(rng_mock::calls==1,"one group sample");}}
